// RgfxGate: a Lilu plugin kext that lets macOS load exactly our reims-graphics
// Metal driver bundle with SIP fully on, and installs that bundle itself at
// first boot. The installer writes the bundle to /Library/GPUBundles and gives
// it the GPU-bundle SIP storage class a stock host carries there, so the
// unmodified Metal loader (gpu_bundle_find_trusted) trusts it; the kernel hooks
// then admit exactly its executable -- by the embedded bundle's code-directory
// hash (RgfxGatePayload.h, generated by tools/pack-payload.py) -- to library
// validation, the signature check and executable mapping, and admit only the
// installer's own writes to that one path. See docs/graphics-kext.
#pragma once

#include <mach/mach_types.h>
#include <sys/kernel_types.h>

struct KernelPatcher; // Lilu

namespace rgfxgate {

// mach/vm_prot.h value; only an executable mapping concerns the sandbox wall.
static constexpr int kVmProtExecute = 0x04;

// Resolved once at patcher load (csfg_get_cdhash is not a KPI symbol).
// Returns a pointer to the mapped file's cdhash, or nullptr; *size is its length.
using t_csfg_get_cdhash = uint8_t *(*)(void *fg, uint64_t offset, size_t *size);
extern t_csfg_get_cdhash gCsfgGetCdhash;

// Set true around the kext's own boot-time install, on exactly one thread, so
// the vnode write hooks admit only that write to the bundle path.
extern volatile bool gInstalling;
extern thread_t gInstallThread;

// True when the fileglob's cdhash is the embedded bundle executable's.
bool cdhashIsOurs(void *fg, uint64_t offset);

// Install the hooks (library validation, mmap, vnode create/unlink) on the
// kernel. Called from the patcher-load callback.
void installHooks(KernelPatcher &patcher);

// Run once at boot: wait for the Data volume, then install/replace the bundle
// in kernel context if missing or different. No-op in the installer/Recovery.
// It publishes the pass on IOResources as kInstallDoneKey: false from its start,
// true once the pass has ended, on every path, so the accelerator registers
// only for a bundle the pass has finished with (RgfxAccelerator.cpp, "the
// bundle").
void startInstaller();

// The IOResources property the install pass publishes (above); the
// accelerator's kRgfxGateInstallDoneKey (RgfxBundlePaths.hpp), kept in step by
// hand.
static constexpr const char *kInstallDoneKey = "RgfxGateInstallDone";

// Rename `from` onto `to` below the vn_* MAC layer (RgfxGateInstall.cpp). With
// swap, both must exist and are exchanged atomically (VFS_RENAME_SWAP);
// otherwise `from` replaces `to`, which need not exist. Returns success. The
// install uses it to swap the staged bundle into place; the AppleGVA preference
// writer uses it to replace the plist atomically.
bool rgfxRenameNode(const char *from, const char *to, bool swap,
                    vfs_context_t ctx);

} // namespace rgfxgate
